package com.sandra.flor

data class Poem(val title: String, val text: String, val author: String)

val poems = listOf(
    Poem("Coincidencia", "Te conozco hace poco,\npero hay encuentros que no necesitan años;\na veces basta una mirada tranquila\npara sentir que algo llegó en el momento correcto.", "Texto original para Sandra"),
    Poem("Poco tiempo", "No cuento los días desde que llegaste,\ncuento las sonrisas que dejaste en ellos.\nY aunque el tiempo sea pequeño,\nlo bonito que siento ya sabe ocupar espacio.", "Texto original para Sandra"),
    Poem("Tu forma de llegar", "Llegaste sin prometer nada\ny aun así trajiste calma.\nTal vez por eso me gustas:\nporque lo sencillo contigo se siente especial.", "Texto original para Sandra"),
    Poem("Calma", "No quiero correr delante del tiempo,\nquiero caminarlo contigo.\nConocerte despacio, reír mucho\ny cuidar cada verdad que vaya naciendo.", "Texto original para Sandra"),
    Poem("Tu risa", "Hay personas que iluminan un lugar,\ny otras que iluminan un día.\nTu risa tiene esa extraña costumbre\nde hacer un poco de las dos cosas.", "Texto original para Sandra"),
    Poem("Cerca", "No necesito tenerte siempre cerca\npara pensar bonito en ti.\nA veces basta recordar tu nombre\ny el día se vuelve un poco más amarillo.", "Texto original para Sandra"),
    Poem("Sin prisa", "Quiero descubrir tus historias\nsin saltarme ninguna página.\nNo para saberlo todo de ti,\nsino para aprender a quererte como eres.", "Texto original para Sandra"),
    Poem("Lo que buscaba", "No sabía poner en palabras lo que buscaba\nhasta que aparecieron pequeños detalles tuyos:\ntu forma de hablar, tu manera de mirar,\ny esa paz que no estaba buscando, pero necesitaba.", "Texto original para Sandra"),
    Poem("Amarillo", "Si pudiera guardar un color para ti,\nsería el amarillo de una flor al sol:\nno porque todo sea perfecto,\nsino porque contigo lo sencillo se siente más vivo.", "Texto original para Sandra"),
    Poem("Un deseo", "No te prometo historias imposibles.\nTe deseo conversaciones largas,\nabrazos sinceros y muchos días\nen los que podamos elegirnos con tranquilidad.", "Texto original para Sandra"),
    Poem("Presente", "Quizá todavía nos falta mucho por conocer,\ny eso también me gusta.\nPorque hoy no necesito adivinar el final:\nme basta disfrutar que estás aquí.", "Texto original para Sandra"),
    Poem("Sandra", "Sandra, entre tantas casualidades\ntú te sentiste diferente.\nNo sé cuánto escribirá el tiempo,\npero esta página contigo ya me parece bonita.", "Texto original para Sandra")
)
